//! Color themes.
//!
//! The effective theme is layered, lowest to highest:
//! 1. the built-in default,
//! 2. `theme = "<name>"` (built-in, or `<config_dir>/vtt/themes/<name>.toml|.conf`),
//!    or `theme_file = "<path>"`,
//! 3. inline `[colors]` from the config,
//! 4. with `adopt_shell_palette`, colors a shell set via OSC 4/10/11/12 (applied at runtime).
//!
//! Theme files are either vtt TOML (the same keys as `[colors]`) or kitty's `key value` format,
//! so any kitty theme, or a file generated by pywal/wallust/matugen, works unchanged.

use std::path::{Path, PathBuf};

use eframe::egui::Color32;

use crate::config::{Config, parse_hex};

pub type Rgb = [u8; 3];

/// A fully resolved theme.
#[derive(Clone, Debug, PartialEq)]
pub struct Theme {
    pub foreground: Rgb,
    pub background: Rgb,
    pub cursor: Rgb,
    pub selection: Rgb,
    /// 256-color table: 0-15 ANSI, 16-231 color cube, 232-255 grayscale.
    pub colors: [Rgb; 256],
    pub accent: Option<Rgb>,
    pub sidebar: Option<Rgb>,
}

/// A partial theme: only the keys a source actually sets.
#[derive(Clone, Debug, Default, PartialEq)]
pub struct Patch {
    pub foreground: Option<Rgb>,
    pub background: Option<Rgb>,
    pub cursor: Option<Rgb>,
    pub selection: Option<Rgb>,
    pub colors: Vec<(u8, Rgb)>,
    pub accent: Option<Rgb>,
    pub sidebar: Option<Rgb>,
}

impl Patch {
    pub fn is_empty(&self) -> bool {
        *self == Patch::default()
    }

    /// Layer `other` on top: its keys win, key by key.
    pub fn merge(&mut self, other: Patch) {
        self.foreground = other.foreground.or(self.foreground);
        self.background = other.background.or(self.background);
        self.cursor = other.cursor.or(self.cursor);
        self.selection = other.selection.or(self.selection);
        self.accent = other.accent.or(self.accent);
        self.sidebar = other.sidebar.or(self.sidebar);
        for (i, c) in other.colors {
            self.colors.retain(|(j, _)| *j != i);
            self.colors.push((i, c));
        }
    }
}

impl Theme {
    pub fn apply(&mut self, p: &Patch) {
        let set = |slot: &mut Rgb, v: Option<Rgb>| {
            if let Some(v) = v {
                *slot = v;
            }
        };
        set(&mut self.foreground, p.foreground);
        set(&mut self.background, p.background);
        set(&mut self.cursor, p.cursor);
        set(&mut self.selection, p.selection);
        for &(i, c) in &p.colors {
            self.colors[i as usize] = c;
        }
        self.accent = p.accent.or(self.accent);
        self.sidebar = p.sidebar.or(self.sidebar);
    }

    pub fn is_light(&self) -> bool {
        luminance(self.background) > 0.5
    }
}

impl Default for Theme {
    fn default() -> Self {
        let mut colors = [[0u8; 3]; 256];
        for (i, c) in colors.iter_mut().enumerate().skip(16) {
            *c = xterm_color(i as u8);
        }
        let mut theme = Theme {
            foreground: [0xcd, 0xd6, 0xf4],
            background: [0x1e, 0x1e, 0x2e],
            cursor: [0xf5, 0xe0, 0xdc],
            selection: [0x58, 0x5b, 0x70],
            colors,
            accent: None,
            sidebar: None,
        };
        let patch = parse_toml(BUILTIN[0].1).expect("built-in default theme parses");
        theme.apply(&patch.0);
        theme
    }
}

/// xterm's default color cube (16-231) and grayscale ramp (232-255).
fn xterm_color(i: u8) -> Rgb {
    match i {
        16..=231 => {
            let i = i - 16;
            let level = |v: u8| if v == 0 { 0 } else { 55 + v * 40 };
            [level(i / 36), level((i / 6) % 6), level(i % 6)]
        }
        232..=255 => {
            let v = 8 + 10 * (i - 232);
            [v, v, v]
        }
        _ => [0, 0, 0],
    }
}

fn luminance([r, g, b]: Rgb) -> f32 {
    (0.2126 * r as f32 + 0.7152 * g as f32 + 0.0722 * b as f32) / 255.0
}

